head.script:
scwin.trigger3_onclick = function(e) {
	// 화면의 GridView 와 같은 id(gridView1)로 setGridStyle
	var gridStr = '<w2:gridView xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" dataList="dataList1" id="gridView1" style="position: relative;width: 500px;height: 150px;">' +
		'<w2:header id="header1">' +
		'<w2:row id="row2">' +
		'<w2:column id="column7" style="height:20px" inputType="text" width="70" value="name1"></w2:column>' +
		'<w2:column id="column3" style="height:20px" inputType="text" width="70" value="name2"></w2:column>' +
		'</w2:row>' +
		'</w2:header>' +
		'<w2:gBody id="gBody4">' +
		'<w2:row id="row5">' +
		'<w2:column id="col1" style="height:20px" inputType="text" width="70"></w2:column>' +
		'<w2:column id="col2" style="height:20px" inputType="text" width="70"></w2:column>' +
		'</w2:row>' +
		'</w2:gBody>' +
		'</w2:gridView>';
	gridView1.setGridStyle(WebSquare.xml.parse(gridStr, true));
};
scwin.trigger4_onclick = function(e) {
	gridView1.remove();
};
